mapper.select:
SELECT c.city_code, c.city_name, c.province_name, c.lon, c.lat,
       m.year, m.month, m.price
FROM t_city c
JOIN t_monthly_price m ON m.city_code = c.city_code

    m.price IS NOT NULL

        AND c.province_name IN

            #{prov}



        AND m.year = #{param.endYear} AND m.month = #{param.endMonth}


        AND m.price >= #{param.minPrice}


        AND m.price <= #{param.maxPrice}


ORDER BY m.price DESC
